import type {IndexPage, IndexCard} from '../../../../schemas/contentful/contentTypes/indexTemplate'

type IndexTemplate = IndexPage['fields']['template']

const makeIndexSchema = (page: IndexTemplate, cards: IndexCard[]) => {
  const indexCards = []
  for (const card of cards) {
    if (card.fields.card?.fields?.heading && card.fields.card?.fields?.description) {
      indexCards.push({
        name: card.fields.card.fields.heading,
        description: card.fields.card.fields.description,
      })
    }
  }

  return {
    '@context': 'https://schema.org',
    '@type': 'CollectionPage',
    name: page?.fields?.hero?.fields?.heading,
    description: page.fields.hero?.fields?.description,
    hasPart: indexCards,
  }
}

const IndexSchema = ({page}: {page: IndexTemplate}) => {
  const cards = page?.fields?.cards ? page.fields.cards.filter(Boolean) : []
  return (
    <script
      type="application/ld+json"
      // eslint-disable-next-line react/no-danger
      dangerouslySetInnerHTML={{__html: JSON.stringify(makeIndexSchema(page, cards))}}
    />
  )
}

export {makeIndexSchema}
export default IndexSchema

try{ IndexSchema.displayName ||= 'IndexSchema' } catch {}